package com.fmrent.cars.dto; import com.fmrent.cars.model.Car; import java.math.BigDecimal; import java.time.Instant;
public record CarResponse(Long id,String name,String category,BigDecimal price,int seats,String transmission,String fuel,String badge,String image,java.util.List<String> images,java.util.List<String> imageFileIds,Instant createdAt){public static CarResponse from(Car c){var gallery=c.getImages().stream().map(com.fmrent.cars.model.CarImage::getUrl).toList();var fileIds=c.getImages().stream().map(com.fmrent.cars.model.CarImage::getFileId).toList();return new CarResponse(c.getId(),c.getName(),c.getCategory(),c.getPrice(),c.getSeats(),c.getTransmission(),c.getFuel(),c.getBadge(),c.getImageUrl(),gallery.isEmpty()?java.util.List.of(c.getImageUrl()):gallery,fileIds,c.getCreatedAt());}}
